p("Two Sum","two-sum","easy",["arrays","hash-table"],["Amazon","Google","Meta"],"Given an array of integers nums and an integer target, return indices of the two numbers that add up to target.",[{"input":"nums = [2,7,11,15], target = 9","output":"[0,1]","explanation":""}],"2 <= nums.length <= 10^4",["Use a hash map to store complements"],[{"input":"4\n2 7 11 15\n9","output":"0 1"},{"input":"3\n3 2 4\n6","output":"1 2"}],[{"input":"2\n3 3\n6","output":"0 1"}],"def twoSum(nums, target):\n    seen = {}\n    for i, n in enumerate(nums):\n        comp = target - n\n        if comp in seen: return [seen[comp], i]\n        seen[n] = i")

p("Reverse String","reverse-string","easy",["strings","two-pointers"],["Microsoft","Apple"],"Write a function that reverses a string.",[{"input":"hello","output":"olleh","explanation":""}],"1 <= s.length <= 10^5",["Use two pointers"],[{"input":"5\nhello","output":"olleh"},{"input":"1\nA","output":"A"}],[{"input":"7\nAbcdEfG","output":"GfEdcba"}],"def reverseString(s):\n    return s[::-1]")

p("Valid Parentheses","valid-parentheses","easy",["stack","strings"],["Amazon","Meta","Bloomberg"],"Given a string s containing just parentheses, determine if the input string is valid.",[{"input":"()","output":"true","explanation":""}],"1 <= s.length <= 10^4",["Use a stack"],[{"input":"2\n()","output":"true"},{"input":"3\n([])","output":"true"}],[{"input":"6\n([{}])","output":"true"}],"def isValid(s):\n    stack = []\n    mapping = {')':'(',']':'[','}':'{'}\n    for c in s:\n        if c in mapping:\n            if not stack or stack[-1] != mapping[c]: return False\n            stack.pop()\n        else: stack.append(c)\n    return not stack")

p("Maximum Subarray","maximum-subarray","easy",["arrays","dynamic-programming"],["Google","Amazon"],"Find the contiguous subarray with the largest sum.",[{"input":"nums = [-2,1,-3,4,-1,2,1,-5,4]","output":"6","explanation":""}],"1 <= nums.length <= 10^5",["Use Kadane's algorithm"],[{"input":"9\n-2 1 -3 4 -1 2 1 -5 4","output":"6"},{"input":"1\n1","output":"1"}],[{"input":"5\n5 4 -1 7 8","output":"23"}],"def maxSubArray(nums):\n    cur = max_sum = nums[0]\n    for n in nums[1:]:\n        cur = max(n, cur + n)\n        max_sum = max(max_sum, cur)\n    return max_sum")

p("Merge Two Sorted Lists","merge-two-sorted-lists","easy",["linked-list","recursion"],["Microsoft","Amazon"],"Merge two sorted linked lists into one sorted list.",[{"input":"list1 = [1,2,4], list2 = [1,3,4]","output":"[1,1,2,3,4,4]","explanation":""}],"Both lists are sorted",["Use a dummy node"],[{"input":"3\n1 2 4\n3\n1 3 4","output":"1 1 2 3 4 4"},{"input":"0\n\n0\n\n","output":""}],[{"input":"1\n2\n1\n1","output":"1 2"}],"def mergeTwoLists(l1, l2):\n    if not l1: return l2\n    if not l2: return l1\n    if l1.val <= l2.val:\n        l1.next = mergeTwoLists(l1.next, l2)\n        return l1\n    l2.next = mergeTwoLists(l1, l2.next)\n    return l2")

p("Best Time to Buy and Sell Stock","best-time-to-buy-sell-stock","easy",["arrays","dynamic-programming"],["Amazon","Meta"],"Find the maximum profit from buying and selling a stock once.",[{"input":"prices = [7,1,5,3,6,4]","output":"5","explanation":""}],"1 <= prices.length <= 10^5",["Track minimum price"],[{"input":"6\n7 1 5 3 6 4","output":"5"},{"input":"5\n7 6 4 3 1","output":"0"}],[{"input":"4\n2 4 1 7","output":"5"}],"def maxProfit(prices):\n    min_price = float('inf')\n    max_profit = 0\n    for p in prices:\n        min_price = min(min_price, p)\n        max_profit = max(max_profit, p - min_price)\n    return max_profit")

p("Binary Search","binary-search","easy",["arrays","searching"],["Microsoft","Amazon"],"Search for a target in a sorted array.",[{"input":"nums = [-1,0,3,5,9,12], target = 9","output":"4","explanation":""}],"O(log n) required",["Classic binary search"],[{"input":"6\n-1 0 3 5 9 12\n9","output":"4"},{"input":"6\n-1 0 3 5 9 12\n2","output":"-1"}],[{"input":"1\n5\n5","output":"0"}],"def search(nums, target):\n    lo, hi = 0, len(nums)-1\n    while lo <= hi:\n        mid = (lo+hi)//2\n        if nums[mid] == target: return mid\n        elif nums[mid] < target: lo = mid+1\n        else: hi = mid-1\n    return -1")

p("Climbing Stairs","climbing-stairs","easy",["dynamic-programming","math"],["Amazon","Apple"],"Climb n stairs using 1 or 2 steps. How many distinct ways?",[{"input":"n = 2","output":"2","explanation":""}],"1 <= n <= 45",["This is Fibonacci"],[{"input":"2","output":"2"},{"input":"3","output":"3"}],[{"input":"5","output":"8"}],"def climbStairs(n):\n    if n <= 2: return n\n    a, b = 1, 2\n    for _ in range(3, n+1):\n        a, b = b, a+b\n    return b")

p("Palindrome Number","palindrome-number","easy",["math"],["Google","Amazon"],"Determine if an integer is a palindrome.",[{"input":"121","output":"true","explanation":""}],"-2^31 <= x <= 2^31-1",["Reverse the number"],[{"input":"121","output":"true"},{"input":"-121","output":"false"}],[{"input":"10","output":"false"}],"def isPalindrome(x):\n    if x < 0: return False\n    return str(x) == str(x)[::-1]")

p("Remove Duplicates from Sorted Array","remove-duplicates-sorted-array","easy",["arrays","two-pointers"],["Amazon"],"Remove duplicates in-place and return new length.",[{"input":"nums = [1,1,2]","output":"2","explanation":""}],"1 <= nums.length <= 3*10^4",["Use two pointers"],[{"input":"3\n1 1 2","output":"2"},{"input":"10\n0 0 1 1 1 2 2 3 3 4","output":"5"}],[{"input":"1\n1","output":"1"}],"def removeDuplicates(nums):\n    if not nums: return 0\n    i = 0\n    for j in range(1, len(nums)):\n        if nums[j] != nums[i]:\n            i += 1\n            nums[i] = nums[j]\n    return i+1")

p("Contains Duplicate","contains-duplicate","easy",["arrays","hash-table"],["Amazon","Google"],"Return true if any value appears at least twice.",[{"input":"nums = [1,2,3,1]","output":"true","explanation":""}],"1 <= nums.length <= 10^5",["Use a set"],[{"input":"4\n1 2 3 1","output":"true"},{"input":"4\n1 2 3 4","output":"false"}],[{"input":"3\n1 1 1","output":"true"}],"def containsDuplicate(nums):\n    return len(nums) != len(set(nums))")

p("Single Number","single-number","easy",["arrays","bit-manipulation"],["Amazon","Google"],"Find the element that appears only once.",[{"input":"nums = [2,2,1]","output":"1","explanation":""}],"1 <= nums.length <= 3*10^4",["Use XOR"],[{"input":"3\n2 2 1","output":"1"},{"input":"5\n4 1 2 1 2","output":"4"}],[{"input":"1\n1","output":"1"}],"def singleNumber(nums):\n    result = 0\n    for n in nums: result ^= n\n    return result")

p("Fizz Buzz","fizz-buzz","easy",["math","strings"],["Amazon","Google"],"Return fizzbuzz array from 1 to n.",[{"input":"5","output":"1 2 Fizz 4 Buzz","explanation":""}],"1 <= n <= 10^4",["Check divisibility by 3 and 5"],[{"input":"5","output":"1 2 Fizz 4 Buzz"},{"input":"3","output":"1 2 Fizz"}],[{"input":"15","output":"1 2 Fizz 4 Buzz Fizz 7 8 Fizz Buzz 11 Fizz 13 14 FizzBuzz"}],"def fizzBuzz(n):\n    return ['Fizz'*(i%3==0)+'Buzz'*(i%5==0) or str(i) for i in range(1,n+1)]")

p("Power of Two","power-of-two","easy",["math","bit-manipulation"],["Amazon"],"Determine if n is a power of two.",[{"input":"16","output":"true","explanation":""}],"0 <= n <= 2^31 - 1",["Use bit manipulation"],[{"input":"16","output":"true"},{"input":"3","output":"false"}],[{"input":"1","output":"true"}],"def isPowerOfTwo(n):\n    return n > 0 and (n & (n-1)) == 0")

p("Valid Anagram","valid-anagram","easy",["strings","hash-table"],["Amazon","Meta"],"Determine if two strings are anagrams.",[{"input":"s = anagram, t = nagaram","output":"true","explanation":""}],"1 <= s.length, t.length <= 5*10^4",["Count character frequencies"],[{"input":"anagram\nnagaram","output":"true"},{"input":"rat\ncar","output":"false"}],[{"input":"a\na","output":"true"}],"def isAnagram(s, t):\n    return sorted(s) == sorted(t)")

p("First Unique Character in a String","first-unique-character","easy",["strings","hash-table"],["Amazon","Google"],"Find the first non-repeating character index.",[{"input":"leetcode","output":"0","explanation":""}],"1 <= s.length <= 10^5",["Count frequencies first"],[{"input":"leetcode","output":"0"},{"input":"aabb","output":"-1"}],[{"input":"loveleetcode","output":"2"}],"def firstUniqChar(s):\n    count = {}\n    for c in s: count[c] = count.get(c, 0) + 1\n    for i, c in enumerate(s):\n        if count[c] == 1: return i\n    return -1")

p("Count Primes","count-primes","easy",["math","arrays"],["Amazon"],"Count primes less than n.",[{"input":"10","output":"4","explanation":"Primes: 2,3,5,7"}],"0 <= n <= 5*10^6",["Use Sieve of Eratosthenes"],[{"input":"10","output":"4"},{"input":"0","output":"0"}],[{"input":"100","output":"25"}],"def countPrimes(n):\n    if n < 3: return 0\n    sieve = [True] * n\n    sieve[0] = sieve[1] = False\n    for i in range(2, int(n**0.5)+1):\n        if sieve[i]:\n            for j in range(i*i, n, i): sieve[j] = False\n    return sum(sieve)",2000)

p("Fibonacci Number","fibonacci-number","easy",["dynamic-programming","math"],["Amazon","Google"],"Return the nth Fibonacci number.",[{"input":"4","output":"3","explanation":"F(4)=3"}],"0 <= n <= 30",["Iterative approach is O(n)"],[{"input":"4","output":"3"},{"input":"2","output":"1"}],[{"input":"10","output":"55"}],"def fib(n):\n    if n <= 1: return n\n    a, b = 0, 1\n    for _ in range(2, n+1): a, b = b, a+b\n    return b")

p("Valid Palindrome","valid-palindrome","easy",["strings","two-pointers"],["Amazon","Meta"],"Check if a string is a palindrome considering only alphanumeric characters.",[{"input":"A man a plan a canal Panama","output":"true","explanation":""}],"1 <= s.length <= 2*10^5",["Use two pointers"],[{"input":"A man a plan a canal Panama","output":"true"},{"input":"race a car","output":"false"}],[{"input":" ","output":"true"}],"def isPalindrome(s):\n    s = ''.join(c.lower() for c in s if c.isalnum())\n    return s == s[::-1]")

p("Missing Number","missing-number","easy",["arrays","math","bit-manipulation"],["Amazon","Google"],"Find the missing number in array [0..n].",[{"input":"nums = [3,0,1]","output":"2","explanation":""}],"n == nums.length",["Use sum formula or XOR"],[{"input":"3\n3 0 1","output":"2"},{"input":"9\n9 6 4 2 3 5 7 0 1","output":"8"}],[{"input":"1\n0","output":"1"}],"def missingNumber(nums):\n    n = len(nums)\n    return n*(n+1)//2 - sum(nums)")

p("Majority Element","majority-element","easy",["arrays","hash-table","sorting"],["Amazon","Google"],"Find the element appearing more than n/2 times.",[{"input":"nums = [2,2,1]","output":"2","explanation":""}],"1 <= nums.length <= 5*10^4",["Boyer-Moore voting algorithm"],[{"input":"3\n2 2 1","output":"2"},{"input":"7\n2 2 1 1 1 2 2","output":"2"}],[{"input":"1\n1","output":"1"}],"def majorityElement(nums):\n    count = candidate = 0\n    for n in nums:\n        if count == 0: candidate = n\n        count += 1 if n == candidate else -1\n    return candidate")

p("Intersection of Two Arrays","intersection-two-arrays","easy",["arrays","hash-table"],["Amazon","Google"],"Return the intersection of two arrays.",[{"input":"nums1=[1,2,2,1], nums2=[2,2]","output":"[2]","explanation":""}],"1 <= nums.length <= 1000",["Use sets"],[{"input":"4\n1 2 2 1\n2\n2 2","output":"2"},{"input":"4\n4 9 5\n9\n9 4 9 8 4","output":"4 9"}],[{"input":"1\n1\n1\n1","output":"1"}],"def intersection(nums1, nums2):\n    return list(set(nums1) & set(nums2))")

p("Rotate Array","rotate-array","easy",["arrays"],["Amazon","Google"],"Rotate array to the right by k steps.",[{"input":"nums=[1,2,3,4,5,6,7], k=3","output":"[5,6,7,1,2,3,4]","explanation":""}],"1 <= nums.length <= 10^5",["Reverse the array"],[{"input":"7\n1 2 3 4 5 6 7\n3","output":"5 6 7 1 2 3 4"},{"input":"4\n-1 -100 3 99\n2","output":"3 99 -1 -100"}],[{"input":"3\n1 2 3\n1","output":"3 1 2"}],"def rotate(nums, k):\n    k %= len(nums)\n    nums[:] = nums[-k:] + nums[:-k]")

p("Longest Common Prefix","longest-common-prefix","easy",["strings"],["Amazon","Google"],"Find the longest common prefix string among an array of strings.",[{"input":"strs = [flower,flow,flight]","output":"fl","explanation":""}],"1 <= strs.length <= 200",["Sort the array first"],[{"input":"3\nflower flow flight","output":"fl"},{"input":"3\ndog racecar car","output":""}],[{"input":"1\na","output":"a"}],"def longestCommonPrefix(strs):\n    if not strs: return ''\n    strs.sort()\n    first, last = strs[0], strs[-1]\n    i = 0\n    while i < len(first) and first[i] == last[i]: i += 1\n    return first[:i]")

p("Reverse Linked List","reverse-linked-list","easy",["linked-list"],["Amazon","Google","Microsoft"],"Reverse a singly linked list.",[{"input":"[1,2,3,4,5]","output":"[5,4,3,2,1]","explanation":""}],"1 <= n <= 5000",["Use three pointers"],[{"input":"5\n1 2 3 4 5","output":"5 4 3 2 1"},{"input":"2\n1 2","output":"2 1"}],[{"input":"1\n1","output":"1"}],"def reverseList(head):\n    prev = None\n    while head:\n        nxt = head.next\n        head.next = prev\n        prev = head\n        head = nxt\n    return prev")

p("Linked List Cycle","linked-list-cycle","easy",["linked-list","two-pointers"],["Amazon","Microsoft"],"Detect if a linked list has a cycle.",[{"input":"head = [3,2,0,-4], pos=1","output":"true","explanation":""}],"0 <= list.length <= 10^4",["Use Floyd's algorithm"],[{"input":"3\n3 2 0 -4\n1","output":"true"},{"input":"2\n1 2\n0","output":"true"}],[{"input":"1\n1\n-1","output":"false"}],"def hasCycle(head):\n    slow = fast = head\n    while fast and fast.next:\n        slow = slow.next\n        fast = fast.next.next\n        if slow == fast: return True\n    return False")

p("Middle of the Linked List","middle-linked-list","easy",["linked-list","two-pointers"],["Amazon"],"Find the middle node of a linked list.",[{"input":"[1,2,3,4,5]","output":"3","explanation":""}],"1 <= n <= 100",["Use slow and fast pointers"],[{"input":"5\n1 2 3 4 5","output":"3"},{"input":"6\n1 2 3 4 5 6","output":"4"}],[{"input":"1\n1","output":"1"}],"def middleNode(head):\n    slow = fast = head\n    while fast and fast.next:\n        slow = slow.next\n        fast = fast.next.next\n    return slow")

p("Sqrt(x)","sqrtx","easy",["math","binary-search"],["Amazon","Microsoft"],"Compute the integer square root of x.",[{"input":"4","output":"2","explanation":""}],"0 <= x <= 2^31-1",["Use binary search"],[{"input":"4","output":"2"},{"input":"8","output":"2"}],[{"input":"0","output":"0"}],"def mySqrt(x):\n    lo, hi = 0, x\n    while lo <= hi:\n        mid = (lo+hi)//2\n        if mid*mid == x: return mid\n        elif mid*mid < x: lo = mid+1\n        else: hi = mid-1\n    return hi")

p("Add Binary","add-binary","easy",["strings","math"],["Amazon"],"Add two binary strings and return the result.",[{"input":"a=11, b=1010","output":"10000","explanation":""}],"1 <= a.length, b.length <= 10^4",["Use carry"],[{"input":"11\n1010","output":"10000"},{"input":"101\n101","output":"1010"}],[{"input":"0\n0","output":"0"}],"def addBinary(a, b):\n    return bin(int(a,2)+int(b,2))[2:]")

p("Number of 1 Bits","number-of-1-bits","easy",["bit-manipulation"],["Amazon"],"Count the number of 1 bits in the binary representation.",[{"input":"11","output":"3","explanation":""}],"The input must be a positive integer.",["Use bit manipulation"],[{"input":"11","output":"3"},{"input":"128","output":"1"}],[{"input":"2147483645","output":"30"}],"def hammingWeight(n):\n    count = 0\n    while n:\n        count += n & 1\n        n >>= 1\n    return count")

p("Reverse Bits","reverse-bits","easy",["bit-manipulation"],["Amazon"],"Reverse bits of a given 32 bits unsigned integer.",[{"input":"43261596","output":"964176192","explanation":""}],"The input must be a 32-bit unsigned integer.",["Process bit by bit"],[{"input":"43261596","output":"964176192"},{"input":"4294967293","output":"3221225471"}],[{"input":"0","output":"0"}],"def reverseBits(n):\n    result = 0\n    for _ in range(32):\n        result = (result << 1) | (n & 1)\n        n >>= 1\n    return result")

p("Happy Number","happy-number","easy",["math","hash-table"],["Amazon"],"Determine if a number is happy.",[{"input":"19","output":"true","explanation":""}],"1 <= n <= 2^31 - 1",["Use a set to detect cycles"],[{"input":"19","output":"true"},{"input":"2","output":"false"}],[{"input":"1","output":"true"}],"def isHappy(n):\n    seen = set()\n    while n != 1 and n not in seen:\n        seen.add(n)\n        n = sum(int(d)**2 for d in str(n))\n    return n == 1")

p("Ugly Number","ugly-number","easy",["math"],["Amazon"],"Determine if a number is ugly (only has factors 2, 3, 5).",[{"input":"6","output":"true","explanation":""}],"-2^31 <= n <= 2^31 - 1",["Keep dividing by 2, 3, 5"],[{"input":"6","output":"true"},{"input":"14","output":"false"}],[{"input":"1","output":"true"}],"def isUgly(n):\n    if n <= 0: return False\n    for p in [2,3,5]:\n        while n % p == 0: n //= p\n    return n == 1")

