p("Plus One","plus-one","easy",["arrays","math"],["Amazon","Google"],"Increment a large integer represented as an array of digits.",[{"input":"digits=[1,2,3]","output":"[1,2,4]","explanation":""}],"1 <= digits.length <= 100",["Handle carry from right to left"],[{"input":"3\n1 2 3","output":"1 2 4"},{"input":"1\n9","output":"1 0"}],[{"input":"4\n9 9 9 9","output":"1 0 0 0 0"}],"def plusOne(digits):\n    for i in range(len(digits)-1,-1,-1):\n        if digits[i]<9: digits[i]+=1; return digits\n        digits[i]=0\n    return [1]+digits")

p("Merge Sorted Array","merge-sorted-array","easy",["arrays","two-pointers"],["Amazon","Google","Microsoft"],"Merge nums2 into nums1 in-place.",[{"input":"nums1=[1,2,3,0,0,0], m=3, nums2=[2,5,6], n=3","output":"[1,2,2,3,5,6]","explanation":""}],"0 <= m,n <= 200",["Merge from the end"],[{"input":"6\n1 2 3 0 0 0\n3\n2 5 6","output":"1 2 2 3 5 6"},{"input":"1\n0\n1\n1","output":"1"}],[{"input":"2\n1 2\n0\n0","output":"1 2"}],"def merge(nums1,m,nums2,n):\n    i,j,k=m-1,n-1,m+n-1\n    while j>=0:\n        if i>=0 and nums1[i]>nums2[j]:\n            nums1[k]=nums1[i]; i-=1\n        else:\n            nums1[k]=nums2[j]; j-=1\n        k-=1")

