p("Sort Colors","sort-colors","medium",["arrays","sorting","two-pointers"],["Amazon","Meta"],"Sort an array of 0s, 1s, and 2s in-place.",[{"input":"nums=[2,0,2,1,1,0]","output":"[0,0,1,1,2,2]","explanation":""}],"n == nums.length",["Dutch National Flag algorithm"],[{"input":"6\n2 0 2 1 1 0","output":"0 0 1 1 2 2"},{"input":"3\n2 0 1","output":"0 1 2"}],[{"input":"1\n0","output":"0"}],"def sortColors(nums):\n    lo,hi=0,len(nums)-1\n    mid=0\n    while mid<=hi:\n        if nums[mid]==0: nums[lo],nums[mid]=nums[mid],nums[lo]; lo+=1; mid+=1\n        elif nums[mid]==1: mid+=1\n        else: nums[mid],nums[hi]=nums[hi],nums[mid]; hi-=1")

p("Flatten Binary Tree to Linked List","flatten-binary-tree","medium",["trees","linked-list","recursion"],["Amazon","Google","Meta"],"Flatten a binary tree to a linked list in-place.",[{"input":"root=[1,2,5,3,4,null,6]","output":"[1,null,2,null,3,null,4,null,5,null,6]","explanation":""}],"0 <= nodes <= 20000",["Reverse pre-order traversal"],[{"input":"3\n1 2 5","output":"1 null 2 null 5"},{"input":"1\n1","output":"1"}],[{"input":"0\nnull","output":""}],"def flatten(root):\n    if not root: return\n    flatten(root.right)\n    flatten(root.left)\n    root.right=flatten.tail\n    root.left=None\n    flatten.tail=root\nflatten.tail=None")

p("Binary Tree Right Side View","binary-tree-right-side","medium",["trees","bfs","dfs"],["Amazon","Google","Meta"],"Return values of nodes visible from the right side.",[{"input":"root=[1,2,3,null,5,null,4]","output":"[1,3,4]","explanation":""}],"1 <= nodes <= 100",["BFS level order, take last of each level"],[{"input":"4\n1 2 3 5","output":"1 3"},{"input":"1\n1","output":"1"}],[{"input":"0\nnull","output":""}],"from collections import deque\ndef rightSideView(root):\n    if not root: return []\n    result=[]\n    queue=deque([root])\n    while queue:\n        level=[]\n        for _ in range(len(queue)):\n            node=queue.popleft()\n            level.append(node.val)\n            if node.left: queue.append(node.left)\n            if node.right: queue.append(node.right)\n        result.append(level[-1])\n    return result")

p("Kth Smallest Element in a BST","kth-smallest-bst","medium",["trees","binary-search","dfs"],["Amazon","Google","Meta"],"Find the kth smallest element in a BST.",[{"input":"root=[3,1,4,null,2], k=1","output":"1","explanation":""}],"1 <= k <= nodes <= 10^4",["In-order traversal"],[{"input":"4\n3 1 4 2\n1","output":"1"},{"input":"3\n5 3 6\n2","output":"3"}],[{"input":"1\n1\n1","output":"1"}],"def kthSmallest(root, k):\n    stack=[]\n    while root or stack:\n        while root:\n            stack.append(root)\n            root=root.left\n        root=stack.pop()\n        k-=1\n        if k==0: return root.val\n        root=root.right")

p("Partition Equal Subset Sum","partition-equal-subset","medium",["dynamic-programming","arrays"],["Amazon","Google"],"Check if array can be partitioned into two subsets with equal sum.",[{"input":"nums=[1,5,11,5]","output":"true","explanation":""}],"1 <= nums.length <= 200",["Subset sum DP"],[{"input":"4\n1 5 11 5","output":"true"},{"input":"3\n1 2 3","output":"false"}],[{"input":"1\n1","output":"false"}],"def canPartition(nums):\n    total=sum(nums)\n    if total%2: return False\n    target=total//2\n    dp={0}\n    for n in nums:\n        new=set()\n        for s in dp:\n            if s+n==target: return True\n            new.add(s); new.add(s+n)\n        dp=new\n    return target in dp")

p("Construct Binary Tree from Preorder and Inorder","construct-binary-tree","medium",["trees","recursion","arrays"],["Amazon","Google","Meta"],"Build a binary tree from preorder and inorder traversals.",[{"input":"preorder=[3,9,20,15,7], inorder=[9,3,15,20,7]","output":"[3,9,20,null,null,15,7]","explanation":""}],"1 <= nodes <= 3000",["Recursion with hash map for inorder indices"],[{"input":"4\n3 9 20 15\n3 9 15 20","output":"tree"},{"input":"1\n1\n1","output":"1"}],[{"input":"2\n1 2\n2 1","output":"1 null 2"}],"def buildTree(preorder, inorder):\n    if not preorder: return None\n    root=TreeNode(preorder[0])\n    mid=inorder.index(preorder[0])\n    root.left=buildTree(preorder[1:mid+1],inorder[:mid])\n    root.right=buildTree(preorder[mid+1:],inorder[mid+1:])\n    return root")

p("Find Peak Element","find-peak-element","medium",["arrays","binary-search"],["Amazon","Google"],"Find a peak element in the array.",[{"input":"nums=[1,2,3,1]","output":"2","explanation":""}],"1 <= nums.length <= 1000",["Binary search"],[{"input":"4\n1 2 3 1","output":"2"},{"input":"3\n1 2 1","output":"1"}],[{"input":"1\n1","output":"0"}],"def findPeakElement(nums):\n    lo,hi=0,len(nums)-1\n    while lo<hi:\n        mid=(lo+hi)//2\n        if nums[mid]<nums[mid+1]: lo=mid+1\n        else: hi=mid\n    return lo")

p("Evaluate Reverse Polish Notation","evaluate-rpn","medium",["stack","arrays"],["Amazon","Google","Meta"],"Evaluate the value of an arithmetic expression in Reverse Polish Notation.",[{"input":"tokens=[2,1,+,3,*]","output":"9","explanation":"(2+1)*3=9"}],"1 <= tokens.length <= 10^4",["Use a stack"],[{"input":"5\n2 1 + 3 *","output":"9"},{"input":"5\n4 13 5 / +","output":"6"}],[{"input":"3\n10 6 9 / + *","output":"6"}],"def evalRPN(tokens):\n    stack=[]\n    for t in tokens:\n        if t in '+-*/':\n            b,a=stack.pop(),stack.pop()\n            if t=='+': stack.append(a+b)\n            elif t=='-': stack.append(a-b)\n            elif t=='*': stack.append(a*b)\n            else: stack.append(int(a/b))\n        else: stack.append(int(t))\n    return stack[0]")

