p("Alien Dictionary","alien-dictionary","hard",["graphs","topological-sort","strings"],["Amazon","Google","Meta"],"Given a sorted dictionary of an alien language, find the order of characters.",[{"input":"words=[wrt,wrf,er,ett,rftt]","output":"wertf","explanation":""}],"1 <= words.length <= 100",["Build graph and topological sort"],[{"input":"5\nwrt wrf er ett rftt","output":"wertf"},{"input":"2\nba bc","output":"abc"}],[{"input":"1\na","output":"a"}],"from collections import defaultdict,deque\ndef alienOrder(words):\n    adj={c:set() for w in words for c in w}\n    for i in range(len(words)-1):\n        w1,w2=words[i],words[i+1]\n        for c1,c2 in zip(w1,w2):\n            if c1!=c2: adj[c1].add(c2); break\n        else:\n            if len(w1)>len(w2): return ''\n    indeg={c:0 for c in adj}\n    for c in adj:\n        for n in adj[c]: indeg[n]+=1\n    queue=deque([c for c in indeg if indeg[c]==0])\n    order=[]\n    while queue:\n        c=queue.popleft()\n        order.append(c)\n        for n in adj[c]:\n            indeg[n]-=1\n            if indeg[n]==0: queue.append(n)\n    return ''.join(order) if len(order)==len(adj) else ''")

p("Longest Increasing Path in a Matrix","longest-increasing-path-matrix","hard",["dynamic-programming","dfs","graphs"],["Amazon","Google","Meta"],"Find the length of the longest increasing path in a matrix.",[{"input":"matrix=[[9,9,4],[6,6,8],[2,1,1]]","output":"4","explanation":""}],"m,n <= 200",["DFS with memoization"],[{"input":"3 3\n9 9 4\n6 6 8\n2 1 1","output":"4"},{"input":"1 1\n1","output":"1"}],[{"input":"1 1\n1","output":"1"}],"def longestIncreasingPath(matrix):\n    if not matrix: return 0\n    R,C=len(matrix),len(matrix[0])\n    dp={}\n    def dfs(r,c):\n        if (r,c) in dp: return dp[(r,c)]\n        ans=1\n        for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:\n            nr,nc=r+dr,c+dc\n            if 0<=nr<R and 0<=nc<C and matrix[nr][nc]>matrix[r][c]:\n                ans=max(ans,1+dfs(nr,nc))\n        dp[(r,c)]=ans\n        return ans\n    return max(dfs(r,c) for r in range(R) for c in range(C))",2000)

p("Palindrome Pairs","palindrome-pairs","hard",["hash-table","strings","trie"],["Amazon","Google","Meta"],"Find all pairs of indices (i,j) such that words[i]+words[j] is a palindrome.",[{"input":"words=[abcd,dcba,abc,ba]","output":"[[0,1],[1,0],[2,3],[3,2]]","explanation":""}],"1 <= words.length <= 5000",["Use hash map with reversed words"],[{"input":"4\nabcd dcba abc ba","output":"pairs"},{"input":"2\na abc","output":"0 1"}],[{"input":"1\na","output":""}],"def palindromePairs(words):\n    d={w:i for i,w in enumerate(words)}\n    result=[]\n    for i,w in enumerate(words):\n        for j in range(len(w)+1):\n            pre=w[:j]\n            suf=w[j:]\n            if pre==pre[::-1]:\n                rev=suf[::-1]\n                if rev in d and d[rev]!=i: result.append([i,d[rev]])\n            if j>0 and suf==suf[::-1]:\n                rev=pre[::-1]\n                if rev in d and d[rev]!=i: result.append([d[rev],i])\n    return result")

p("Cherry Pickup","cherry-pickup","hard",["dynamic-programming","arrays"],["Amazon","Google"],"Collect maximum cherries on an NxN grid with two robots starting from (0,0) and going to (N-1,N-1) and back.",[{"input":"grid=[[0,1,-1],[1,0,-1],[1,1,1]]","output":"5","explanation":""}],"1 <= grid.length <= 50",["DP with two paths"],[{"input":"3 3\n0 1 -1\n1 0 -1\n1 1 1","output":"5"},{"input":"1 1\n1","output":"1"}],[{"input":"1 1\n1","output":"1"}],"def cherryPickup(grid):\n    N=len(grid)\n    dp={}\n    def dfs(r1,c1,r2):\n        c2=r1+c1-r2\n        if r1>=N or c1>=N or r2>=N or c2>=N or grid[r1][c1]==-1 or grid[r2][c2]==-1:\n            return float('-inf')\n        if r1==N-1 and c1==N-1: return grid[r1][c1]\n        if (r1,c1,r2) in dp: return dp[(r1,c1,r2)]\n        cherries=grid[r1][c1]\n        if r1!=r2 or c1!=c2: cherries+=grid[r2][c2]\n        best=max(dfs(r1+1,c1,r2+1),dfs(r1+1,c1,r2),dfs(r1,c1+1,r2+1),dfs(r1,c1+1,r2))\n        dp[(r1,c1,r2)]=cherries+best\n        return dp[(r1,c1,r2)]\n    return max(0,dfs(0,0,0))",2000)

p("Best Time to Buy and Sell Stock IV","buy-sell-stock-iv","hard",["dynamic-programming","arrays"],["Amazon","Google","Meta"],"Find the maximum profit from at most k transactions.",[{"input":"k=2, prices=[2,4,1]","output":"2","explanation":""}],"0 <= k <= 100",["DP with transaction count"],[{"input":"3\n2 4 1\n2","output":"2"},{"input":"2\n3 2 6 5 0 3\n2","output":"7"}],[{"input":"2\n1 2\n1","output":"1"}],"def maxProfit(k, prices):\n    if not prices: return 0\n    n=len(prices)\n    if k>=n//2:\n        return sum(max(0,prices[i]-prices[i-1]) for i in range(1,n))\n    dp=[[0]*n for _ in range(k+1)]\n    for t in range(1,k+1):\n        maxDiff=-prices[0]\n        for i in range(1,n):\n            dp[t][i]=max(dp[t][i-1],prices[i]+maxDiff)\n            maxDiff=max(maxDiff,dp[t-1][i]-prices[i])\n    return dp[k][n-1]",2000)

